    const frm = $('.frm', st), HIDDEN = [[v => v.length >= 8, 'Must be at least 8 characters'], [v => /[A-Z]/.test(v), 'Must contain a capital letter'], [v => /\d/.test(v), 'Must contain a number'], [v => /[^A-Za-z0-9]/.test(v), 'Must contain a symbol']];
